tsid = '20f10a84-4ec1-54ad-896a-1b534d833709'
vals = {}
import csv
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        if row['timeseries_id'] == tsid:
            vals[row['timestamp']] = float(row['value'])

dates = ['2018-10-0%d' % d for d in range(4,10)] + ['2018-10-1%d' % d for d in range(0,3)]
occ = unocc = 0.0
n_occ = n_un = 0
for d in dates:
    for hr in range(24):
        key = '%sT%02d:00:00' % (d, hr)
        if key in vals:
            v = vals[key]
            if 8 <= hr <= 18:
                occ += v; n_occ += 1
            else:
                unocc += v; n_un += 1

print('occupied hours count:', n_occ, 'occ J:', occ)
print('unoccupied hours count:', n_un, 'unocc J:', unocc)
print('occupied changed MORE?', occ > unocc)
print('unoccupied changed MORE?', unocc > occ)
